"""Backgrounds, props and visual effects. All artwork is generated by code (original)."""
from __future__ import annotations

import functools
import math
import random

from PIL import Image, ImageDraw, ImageFilter

from . import config
from .draw import Pen, font, make_sprite, rgba, shade

BG_RES = 2  # background pixels per world unit (world frame is 1080x1920 units)


# ----------------------------------------------------------------------------
# Backgrounds
# ----------------------------------------------------------------------------
def _canvas(scale=4):
    W, H = config.WIDTH * scale, config.HEIGHT * scale
    img = Image.new("RGBA", (W, H), (0, 0, 0, 255))
    return img, Pen(img, scale, 0, 0)


def _finish(img):
    return img.resize((config.WIDTH * BG_RES, config.HEIGHT * BG_RES), Image.LANCZOS)


