def living_room(p: Pen):
    p.rect(0, 0, 1080, 1560, fill="#C8B6E2")
    for x in range(30, 1080, 120):
        p.line([(x, 0), (x, 1560)], color="#BBA6D8", width=8, round_caps=False)
    p.rrect(140, 380, 520, 700, 10, fill="#2B2F36", width=8)      # TV
    p.rrect(160, 400, 500, 680, 6, fill="#3B4A6B", outline=None, width=0)
    p.rrect(110, 700, 560, 760, 10, fill="#7A4A2A", width=6)
    p.rrect(640, 420, 960, 640, 8, fill="#F2D49B", width=6)       # picture frame
    p.heart(800, 530, 120, "#F6A8D3")
    p.rect(0, 1560, 1080, 1920, fill="#9C6B3F")
